CREATE COLUMN TABLE "TEST_AP"."APZ_OHEC" ("empID" INTEGER CS_INT NOT NULL , "contractID" INTEGER CS_INT NOT NULL , "code" NVARCHAR(50), "type" INTEGER CS_INT, "dept" INTEGER CS_INT, "branch" INTEGER CS_INT, "signer" INTEGER CS_INT, "signDate" LONGDATE CS_LONGDATE, "startDate" LONGDATE CS_LONGDATE, "endDate" LONGDATE CS_LONGDATE, "ProbSalary" DECIMAL(19,6) CS_FIXED, "basicSalary" DECIMAL(19,6) CS_FIXED, "salary" DECIMAL(19,6) CS_FIXED, "salaryCurr" NVARCHAR(3), "PymMeth" NVARCHAR(2) DEFAULT '5', "note" NVARCHAR(254), "BPLId" INTEGER CS_INT, "ParentContract" INTEGER CS_INT, PRIMARY KEY ("empID", "contractID")) UNLOAD PRIORITY 5  AUTO MERGE 